#include <iostream>
#include <string>
#include <vector>

std::string signal_name(int sig) {
    switch (sig) {
        case 6:
            return "SIGABRT";
        case 8:
            return "SIGFPE";
        case 11:
            return "SIGSEGV";
        default:
            return "signal " + std::to_string(sig);
    }
}

void describe(int status) {
    std::cout << status << ": ";
    if (status == 0) {
        std::cout << "success\n";
    } else if (status > 128) {
        std::cout << "killed by " << signal_name(status - 128) << '\n';
    } else {
        std::cout << "exited with " << status << '\n';
    }
}

int main() {
    std::vector<int> statuses = {0, 1, 134, 136, 139, 141};
    for (int status : statuses) {
        describe(status);
    }
    return 0;
}

