#include <iostream>
#include <optional>
#include <vector>

const int* find_qty(const std::vector<int>& ids, const std::vector<int>& qtys, int id) {
    for (std::size_t i = 0; i < ids.size(); ++i) {
        if (ids[i] == id) {
            return &qtys[i];
        }
    }
    return nullptr;
}

std::optional<int> remaining(const std::vector<int>& ids, const std::vector<int>& qtys, int id, int filled) {
    const int* qty = find_qty(ids, qtys, id);
    if (qty == nullptr) {
        return std::nullopt;
    }
    return *qty - filled;
}

int main() {
    std::vector<int> ids = {11, 12, 13};
    std::vector<int> qtys = {500, 300, 200};
    std::vector<int> query_ids = {12, 14, 13};
    std::vector<int> query_fills = {100, 50, 200};
    for (std::size_t i = 0; i < query_ids.size(); ++i) {
        std::optional<int> left = remaining(ids, qtys, query_ids[i], query_fills[i]);
        std::cout << "order " << query_ids[i] << ": ";
        if (left.has_value()) {
            std::cout << *left << " left\n";
        } else {
            std::cout << "unknown\n";
        }
    }
    return 0;
}

