#include <cstddef>
#include <iostream>
#include <vector>

// Fast: keeps a running sum of the last 3 sizes. It has a bug.
std::vector<int> fast_sums(const std::vector<int>& sizes) {
    std::vector<int> sums;
    int sum = 0;
    for (std::size_t i = 0; i < sizes.size(); ++i) {
        sum += sizes[i];
        if (i > 3) {
            sum -= sizes[i - 3];  // drop the size that left the window
        }
        sums.push_back(sum);
    }
    return sums;
}

// Slow: adds the window up again at every step, so it is obviously right.
int slow_sum(const std::vector<int>& sizes, std::size_t i) {
    std::size_t first = i >= 2 ? i - 2 : 0;
    int sum = 0;
    for (std::size_t j = first; j <= i; ++j) {
        sum += sizes[j];
    }
    return sum;
}

int main() {
    std::vector<int> sizes = {100, 200, 300, 400, 500, 600};
    std::vector<int> fast = fast_sums(sizes);
    for (std::size_t i = 0; i < sizes.size(); ++i) {
        int slow = slow_sum(sizes, i);
        if (fast[i] != slow) {
            std::cout << "first mismatch at step " << i << '\n';
            std::cout << "fast " << fast[i] << ", slow " << slow << '\n';
            return 0;
        }
    }
    std::cout << "all " << sizes.size() << " steps agree\n";
    return 0;
}

