#include <cstddef>
#include <iostream>
#include <vector>

// Fast: updates a running average in whole cents. Don't change it.
std::vector<int> fast_averages(const std::vector<int>& prices) {
    std::vector<int> averages;
    int avg = 0;
    for (std::size_t i = 0; i < prices.size(); ++i) {
        int n = static_cast<int>(i) + 1;
        avg += (prices[i] - avg) / n;
        averages.push_back(avg);
    }
    return averages;
}

int slow_average(const std::vector<int>& prices, std::size_t i) {
    int sum = 0;
    for (std::size_t j = 0; j <= i; ++j) {
        sum += prices[j];
    }
    return sum / static_cast<int>(i + 1);
}

int main() {
    std::vector<int> prices = {10000, 10003, 10003, 10004, 10006};
    std::vector<int> fast = fast_averages(prices);
    for (std::size_t i = 0; i < prices.size(); ++i) {
        int slow = slow_average(prices, i);
        if (fast[i] != slow) {
            std::cout << "first mismatch at step " << i << '\n';
            std::cout << "fast " << fast[i] << ", slow " << slow << '\n';
            return 0;
        }
    }
    std::cout << "all " << prices.size() << " steps agree\n";
    return 0;
}
